 static int n;static void Check(bool ok,string name){if(!ok)throw new Exception(name);n++;Console.WriteLine("PASS "+name);}static void Reject(Action work,string name){bool failed=false;try{work();}catch{failed=true;}Check(failed,name);}
 public static int Main(string[] args){try{string root=args[0];Directory.CreateDirectory(Path.Combine(root,"config","profiles"));Directory.CreateDirectory(Path.Combine(root,"state"));var s=new DesktopService(root);s.ScriptOverride=(name,value)=>"test action";var launches=new List<ProcessStartInfo>();s.LaunchOverride=x=>{lock(launches)launches.Add(x);};string folder=Path.Combine(root,"개발 프로젝트 (한글) ' & $ ; %");Directory.CreateDirectory(folder);string child=Path.Combine(folder,"앱 1");Directory.CreateDirectory(child);File.WriteAllText(Path.Combine(child,"package.json"),"{}");string nested=Path.Combine(child,"서버");Directory.CreateDirectory(nested);Directory.CreateDirectory(Path.Combine(folder,".hidden"));Directory.CreateDirectory(Path.Combine(folder,"node_modules"));s.RegisterRoot(folder);s.RegisterRoot(folder);Check(s.Developer().Roots.Count==1,"Root duplicate rejected without duplication");var scan=s.DiscoverProjects();Check(scan.Length==1&&scan[0].Directory==child,"Default one-level scan ignores hidden and dependencies");Check(s.ProjectType(child)=="Node.js","Project recognition uses marker only");Check(launches.Count==0,"Scanning never launches scripts or tools");var config=s.Developer();config.ScanDepth=2;config.ShowHidden=true;s.SaveDeveloper(config);Check(s.DiscoverProjects().Any(x=>x.Directory==nested),"Bounded deeper scanning");Check(s.DiscoverProjects().Any(x=>Path.GetFileName(x.Directory)==".hidden"),"Hidden folders opt-in");config.ScanDepth=6;Reject(()=>s.SaveDeveloper(config),"Depth greater than five rejected");config.ScanDepth=1;s.SaveDeveloper(config);
 var p=s.RegisterDiscovered(scan[0]);p.Pinned=true;p.Developer=new DeveloperPreferences{TerminalHost="cmd",WslDistribution="Test-Ubuntu",WslUser="tester"};s.SaveProject(p);s.SelectProject(p.Id);Check(s.ActiveProject().Id==p.Id,"Selected project persists in existing registry");Check(s.Preferences(p).TerminalHost=="cmd"&&s.Preferences(p).CodexExecutable=="codex","Project override plus global inheritance");Check(s.Projects().Length==1,"No second project database");s.RemoveRoot(folder);Check(Directory.Exists(child)&&s.Projects().Length==1,"Removing root preserves folders and projects");Reject(()=>s.RegisterRoot(Path.Combine(root,"missing")),"Missing root is not created");
 string exe=Process.GetCurrentProcess().MainModule.FileName;GuntConfiguration.Save(root,"apps",new Dictionary<string,object>{{"terminal",exe},{"code",exe},{"git",exe}});GuntConfiguration.Save(root,"monitor",new Dictionary<string,object>{{"compact",false},{"width",360}});
 s.WslUserResolver=(d,u)=>"tester";string converted="/mnt/c/개발 프로젝트 (한글) ' & $ ; %/앱 1";string distroSeen=null,originalPath=null;bool missing=false,rootUser=false;var queries=new List<string[]>();s.QueryOverride=(binary,a,timeout,encoding)=>{queries.Add(a);if(a.Contains("--list")){if(encoding!=Encoding.Unicode)throw new Exception("WSL list UTF16 required");return "Test-Ubuntu\r\nOther\r\n";}if(a.Contains("--distribution"))distroSeen=a[Array.IndexOf(a,"--distribution")+1];if(a.Contains("wslpath")){originalPath=a.Last();return converted+"\n";}if(a.Last()=="id -un")return rootUser?"root\n":"tester\n";if(a.Last().Contains("__GUNT_PATH__")){if(missing)throw new IOException("not installed");return "\n__GUNT_PATH__/usr/bin/codex\ncodex-cli test\n";}if(a.Contains("rev-parse"))return child;if(a.Contains("symbolic-ref"))return "feature/test\n";if(a.Contains("status"))return " M changed.cs\0?? new.cs\0R  renamed.cs\0old.cs\0";return "";};
 string wsl=s.WslPath(child,"Test-Ubuntu");Check(wsl==converted&&originalPath==child&&distroSeen=="Test-Ubuntu","Exact Unicode Windows path passed to wslpath with selected distro");Check(queries.Where(a=>a.Contains("--distribution")).All(a=>a.Contains("--user")&&a.Contains("tester")),"Every WSL query explicitly uses normal account");Reject(()=>s.WslPath(child,"Missing"),"Unavailable distro rejected");rootUser=true;Reject(()=>s.WslPath(child,"Test-Ubuntu"),"Root runtime account rejected");rootUser=false;Check(s.ProbeTool("Test-Ubuntu","codex").Available,"CLI marker and version detection");missing=true;int before=launches.Count;Reject(()=>s.LaunchDeveloper(p,"opencode"),"Missing CLI prevents launch");Check(launches.Count==before,"No terminal from wrong directory when CLI missing");missing=false;s.LaunchDeveloper(p,"codex");var cmd=launches.Last();Check(cmd.FileName=="cmd.exe"&&cmd.WorkingDirectory==child&&!cmd.RedirectStandardInput&&!cmd.RedirectStandardOutput,"CMD launcher remains visible and interactive with exact cwd");string payload=Encoding.Unicode.GetString(Convert.FromBase64String(cmd.Arguments.Split(' ').Last()));Check(payload.Contains("--user")&&payload.Contains("tester")&&payload.Contains(converted.Replace("'","''")),"CMD payload carries exact WSL directory and account as data");s.LaunchDeveloper(p,"codex",new DeveloperPreferences{TerminalHost="windows-terminal",WslDistribution="Test-Ubuntu",WslUser="tester",CodexExecutable="codex"});Check(launches.Last().FileName==exe&&launches.Last().Arguments.Contains("EncodedCommand"),"Windows Terminal launcher uses shared WSL builder");Check(DesktopService.Posix("a'b")=="'a'\"'\"'b'","POSIX apostrophe escaping");s.LaunchDeveloper(p,"ide");Check(launches.Last().Arguments=="--new-window "+DesktopService.Quote(child),"VS Code receives exact directory");s.LaunchDeveloper(p,"powershell");Check(launches.Last().WorkingDirectory==child,"PowerShell exact working directory");var git=s.GitStatus(p);Check(git.Branch=="feature/test"&&git.Modified==2&&git.Untracked==1,"Git NUL records and rename counts accurate");int queryCount=queries.Count;s.GitStatus(p);Check(queryCount==queries.Count,"Git query cache avoids repeat scan");Check(queries.Where(a=>a.Contains("status")).All(a=>a.Contains("core.fsmonitor=false")&&a.Contains("--no-optional-locks")),"Git read disables project fsmonitor execution and optional locks");
 Check(s.Sessions().Presets.Count==4,"Four built-in session templates");var session=new DevelopmentSession{Id="test-session",Name="테스트",Actions=new List<SessionAction>{new SessionAction{Kind="ide"},new SessionAction{Kind="folder"}}};s.SaveSession(session);var run=s.StartSession(p,session);Check(run.Actions.Count==2&&run.Actions.All(x=>x.Status=="요청 전달"),"Sequential session reports individual requests");Reject(()=>s.StartSession(p,session),"Double start blocked");Check(s.SessionHistory().Length==1&&s.ResumeConfiguration().Item1.Id==p.Id,"Bounded history and resume retain project and preferences");s.EndDevelopmentSession();Check(!s.SessionHistory().First().Active,"Manual session end records without killing tools");var independent=new DevelopmentSession{Id="independent",Name="독립",Mode="independent",Actions=new List<SessionAction>{new SessionAction{Kind="ide"},new SessionAction{Kind="repository"},new SessionAction{Kind="command"}}};s.SaveSession(independent);var result=s.StartSession(p,independent);Check(result.Actions.Count(x=>x.Status=="건너뜀")==2,"Optional URL and commands skipped truthfully");Reject(()=>s.DeleteSession("ai-coding"),"Built-in session deletion protected");s.DeleteSession("test-session");Check(!s.Sessions().Presets.Any(x=>x.Id=="test-session"),"User session delete persists");
 Check(s.SearchCommands("cdx").Any(x=>x.Id=="codex"),"Fuzzy English alias search");Check(s.SearchCommands("개발").Any(x=>x.Id=="developer"),"Korean command search");s.SaveAlias("mine","codex");Check(s.SearchCommands("MINE").Single().Id=="codex","Case-insensitive custom alias");Reject(()=>s.SaveAlias("Mine","opencode"),"Alias collision never overwrites");Reject(()=>s.SaveAlias("cx","opencode"),"Built-in alias collision rejected");s.FavoriteCommand("codex");Check(s.SearchCommands("").First().Id=="codex","Favorite commands persist and rank first");s.RememberCommand("opencode");Check(s.CommandsConfig().Recent.First()=="opencode","Recent command persists");
 var state=new Dictionary<string,object>{{"compact",false},{"monitorVisible",true},{"manualPaused",false}};s.WorkspaceOverride=()=>new Dictionary<string,object>(state);int count=0;s.ScriptOverride=(script,a)=>{count++;if(a.Contains("monitor-hide"))state["monitorVisible"]=false;if(a.Contains("monitor-show"))state["monitorVisible"]=true;return "test action";};var rule=new AutomationRule{Name="테스트 규칙",Trigger="session-started",Action="monitor-hide"};s.SaveRule(rule);s.RunAutomationRule(rule.Id);Check(count==0,"Automation disabled by default");rule.Enabled=true;s.SaveRule(rule);s.RunAutomationRule(rule.Id);Check(!Convert.ToBoolean(state["monitorVisible"])&&count==1,"Explicitly enabled rule uses shared action adapter");s.RunAutomationRule(rule.Id);Check(count==1,"Cooldown prevents repeated rule action");state["compact"]=true;Check(s.RestoreAutomationOwnership().Contains("수동 변경")&&count==1,"Automation never overwrites later manual edits");state["compact"]=false;s.RestoreAutomationOwnership();Check(Convert.ToBoolean(state["monitorVisible"]),"Owned state restoration returns previous visibility");Check(s.RestoreAutomationOwnership().Contains("없습니다"),"Owned restoration consumed once");var forbidden=new AutomationRule{Name="반복",Trigger="session-started",Action="session",Value="ai-coding"};Reject(()=>s.SaveRule(forbidden),"Recursive session rule refused");rule.CooldownSeconds=0;Reject(()=>s.SaveRule(rule),"Invalid automation interval rejected");Check(!File.Exists(Path.Combine(root,"executed")),"No arbitrary project script executed in tests");Console.WriteLine("VERIFIED "+n);return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
